package com.pokedaisy.app.companion.data

// GENERATED by scripts/gen_cfru_party_assets.py from each hack's live
// gBaseStats (genderRatio = u8 at +0x10 of each 28-byte record, by the hack's
// own species ids) - do not hand-edit. Same meaning as genderRatiosFireRed:
// 0 always male, 254 always female, 255 genderless, else female when
// (personality & 0xFF) < ratio.

internal fun unhexRatios(s: String) = IntArray(s.length / 2) { s.substring(it * 2, it * 2 + 2).toInt(16) }

/** Unbound: gBaseStats @ ROM 0x19E0C9C, species 0..1293. */
val genderRatiosUnbound: IntArray by lazy { unhexRatios("") }

/** RadicalRed: gBaseStats @ ROM 0x17B98EC, species 0..1322. */
val genderRatiosRadicalRed: IntArray by lazy { unhexRatios("") }

/** Odyssey: gBaseStats @ ROM 0x254784, species 0..411. */
val genderRatiosOdyssey: IntArray by lazy { unhexRatios("") }

/** Amethyst: gBaseStats @ ROM 0x1BC257C, species 0..1267. */
val genderRatiosAmethyst: IntArray by lazy { unhexRatios("") }

/** AmethystV141: gBaseStats @ ROM 0x1A98390, species 0..1293. */
val genderRatiosAmethystV141: IntArray by lazy { unhexRatios("") }
